using NetComponents.extensions;using System;using System.ComponentModel;using System.Drawing.Design;using System.Globalization;using System.Linq;using System.Windows.Forms;using System.Windows.Forms.Design;namespace LessonEditor.components {	public partial class GridViewEditor:UITypeEditor {		/// <summary>		/// Grid table Editor		/// @source		/// https://stackoverflow.com/questions/32582504/propertygrid-expandable-collection		/// <code>		/// @example		///[CategoryAttribute("INTEARKTIVITA"),		///	PropertyOrder(7),		///	DisplayName("Seznam"),		///	DescriptionAttribute("Seznam"),		///	Browsable(false), // changes at runtime		///	TypeConverter(typeof(ListDataConverter)),		///	GridViewEditor.Arguments("Na každém řádku je jedna položka.", "Editor položek:"),		///	Editor(typeof(GridViewEditor), typeof(UITypeEditor))		///]		///CheckedString[] TextCheckList { get; set; }		/// </code>		/// </summary>		public GridViewEditor() {		}		public override UITypeEditorEditStyle GetEditStyle(ITypeDescriptorContext context) {			return UITypeEditorEditStyle.Modal;		}		public override object EditValue(ITypeDescriptorContext context, IServiceProvider provider, object value) {			var editorService = provider.GetService(typeof(IWindowsFormsEditorService)) as IWindowsFormsEditorService;			if (editorService != null) {				// Read Arguments				string message = string.Empty, title = string.Empty;				//get attributes with your arguments. there should be one such attribute.				var propertyAttributes = context.PropertyDescriptor.Attributes.OfType<Arguments>();				if (propertyAttributes.Count() > 0) {					var argumentsAttribute = propertyAttributes.First();					message = argumentsAttribute.WindowMessage;					title = argumentsAttribute.WindowTitle;				}				var selectionControl = new GridViewCtrl(editorService, (GridViewColumnData[])value, message, title);				editorService.DropDownControl(selectionControl);				editorService.CloseDropDown();				//Console.WriteLine("GridViewEditor > EditValue > DialogResult:{0} Value:{1}", selectionControl.DialogResult, selectionControl.Value.ListToString("\n\t"));				if (selectionControl.DialogResult == DialogResult.OK) value = selectionControl.Value;			}			return value ?? new GridViewColumnData[0];		}		/// <summary> Customize message and title for GridViewEditor </summary>		internal class Arguments:Attribute {			public string WindowMessage { get; private set; }			public string WindowTitle { get; private set; }			public Arguments(string windowMessage, string windowTitle) {				WindowMessage = windowMessage;				WindowTitle = windowTitle;			}		}	}	#region TypeConverter	/// <summary>	/// Add this to properties that implement GridViewColumnData[]	/// <code>	/// @example	///  [TypeConverter(typeof(GridViewDataConverter))]	/// </code>	/// </summary>	public class GridViewDataConverter:CollectionConverter {		public override bool GetPropertiesSupported(ITypeDescriptorContext context) {			return true;		}		public override PropertyDescriptorCollection GetProperties(ITypeDescriptorContext context, object value, Attribute[] attributes) {			if (value is GridViewColumnData[] list && list.Length > 0) {				var items = new PropertyDescriptorCollection(null);				for (int i = 0; i < list.Length; i++) {					//var item = list[i];//item.ColumnItems					items.Add(new ExpandableCollectionPropertyDescriptor(list, i));				}				return items;			}			return base.GetProperties(context, value, attributes);		}		public override object ConvertTo(ITypeDescriptorContext pContext, CultureInfo pCulture, object value, Type pDestinationType) {			if (pDestinationType == typeof(string) && value is GridViewColumnData[] list) {				var cnt = (list == null) ? 0 : list.Length;				return $"{cnt}"; // počet položek			}			return base.ConvertTo(pContext, pCulture, value, pDestinationType);		}	}	#endregion}